import { writeFileSync } from "node:fs";
import { dishes, restaurants } from "../src/lib/data";
const q = (s: string) => `'${s.replaceAll("'", "''")}'`;
const a = (values: string[]) => `array[${values.map(q).join(",")}]::text[]`;
const lines = [
  "-- Generated by npm run db:seed:generate from src/lib/data.ts. Fictional demo recipes.",
  "begin;",
];
for (const r of restaurants)
  lines.push(
    `insert into public.restaurants(id,name,description,accepting_orders,delivery_postal_codes,delivery_fee_cents) values(${q(r.id)},${q(r.name)},${q(r.description)},${r.open},${a(r.zipCodes)},${r.deliveryFee}) on conflict(id) do nothing;`,
  );
for (const d of dishes) {
  lines.push(
    `insert into public.dishes(id,restaurant_id,name,description,cuisine,price_cents,is_available,recipe_verified_at,prep_minutes,delivery_min,delivery_max) values(${q(d.id)},${q(d.restaurantId)},${q(d.name)},${q(d.description)},${q(d.cuisine)},${d.price},${d.available},now(),15,${d.minutes[0]},${d.minutes[1]}) on conflict(id) do nothing;`,
  );
  lines.push(
    `insert into public.dish_attributes(dish_id,spice_level,texture,flavors,temperature,richness,source,verified_at) values(${q(d.id)},${d.spice},${a(d.tags)},${a(d.tags)},${q(d.temperature)},${q(d.richness)},'merchant',now()) on conflict(dish_id) do nothing;`,
  );
  lines.push(
    `insert into public.dish_images(dish_id,storage_path,alt_text,sort_order,provenance) values(${q(d.id)},'/food-editorial.png#tile=${d.image}',${q(d.name)},0,'Generated with OpenAI ImageGen for this demo; illustrative recipe styling') on conflict(dish_id,sort_order) do nothing;`,
  );
  for (const value of d.ingredients) {
    lines.push(
      `insert into public.ingredients(id,name) values(${q(value)},${q(value)}) on conflict do nothing;insert into public.dish_ingredients values(${q(d.id)},${q(value)}) on conflict do nothing;`,
    );
  }
  for (const value of d.allergens) {
    lines.push(
      `insert into public.allergens(id,name) values(${q(value)},${q(value)}) on conflict do nothing;insert into public.dish_allergens values(${q(d.id)},${q(value)}) on conflict do nothing;`,
    );
  }
  for (const value of d.dietary) {
    lines.push(
      `insert into public.dietary_attributes(id,name) values(${q(value)},${q(value)}) on conflict do nothing;insert into public.dish_dietary_attributes values(${q(d.id)},${q(value)},now()) on conflict do nothing;`,
    );
  }
  for (const m of d.modifiers)
    lines.push(
      `insert into public.dish_modifiers(id,dish_id,name,price_cents) values(${q(`${d.id}:${m.id}`)},${q(d.id)},${q(m.name)},${m.price}) on conflict do nothing;`,
    );
  lines.push(
    `insert into public.dish_inventory(dish_id,tracked,untracked_policy) values(${q(d.id)},false,'manual_review') on conflict do nothing;`,
  );
}
lines.push("commit;");
writeFileSync("supabase/seed.sql", lines.join("\n") + "\n");
